class Account:
    def __init__(self, balance): self._balance = balance
    @property
    def balance(self): return self._balance
a = Account(80)
print(a.balance)

class Account:
    def __init__(self): self._balance = 0
    def deposit(self, amount):
        if amount <= 0: raise ValueError('positive amount required')
        self._balance += amount
a = Account(); a.deposit(25)
print(a._balance)
